sys_script_include.script:
var EventDashboardUtils = Class.create();
EventDashboardUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getUpcomingEvents: function() {
        var events = [];
        var gr = new GlideRecord('x_1790227_event_ma_event');
        gr.addQuery('u_event_date', '>=', gs.nowDateTime());
        gr.query();

        while (gr.next()) {
            events.push({
                sys_id: gr.getUniqueValue(),
                name: gr.getValue('u_event_name'),
                date: gr.getDisplayValue('u_event_date'),
                location: gr.getValue('u_location'),
                status: gr.getValue('u_status')
            });
        }
        return JSON.stringify(events);
    },

    getEventDetails: function() {
        var eventId = this.getParameter('sysparm_eventId');
        var data = {};

        // Tasks
        data.tasks = [];
        var taskGR = new GlideRecord('x_1790227_event_ma_event_task');
        taskGR.addQuery('u_event_id', eventId);
        taskGR.query();
        while (taskGR.next()) {
            data.tasks.push({ name: taskGR.getValue('u_task_name'), status: taskGR.getValue('u_status') });
        }

        // Attendees
        data.attendees = [];
        var attendeeGR = new GlideRecord('x_1790227_event_ma_attendee');
        attendeeGR.addQuery('u_event_id', eventId);
        attendeeGR.query();
        while (attendeeGR.next()) {
            data.attendees.push({ name: attendeeGR.getValue('u_attendee_id') });
        }

        // Vendors
        data.vendors = [];
        var vendorGR = new GlideRecord('x_1790227_event_ma_vendor');
        vendorGR.addQuery('u_event_id', eventId);
        vendorGR.query();
        while (vendorGR.next()) {
            data.vendors.push({ name: vendorGR.getValue('u_vendor_name') });
        }

        // Budget
        var budgetGR = new GlideRecord('x_1790227_event_ma_budget');
        budgetGR.addQuery('u_event_id', eventId);
        budgetGR.query();
        if (budgetGR.next()) {
            data.budget = {
                total: budgetGR.getValue('u_total_budget'),
                spent: budgetGR.getValue('u_amount_spent'),
                remaining: budgetGR.getValue('u_amount_remaining'),
                status: budgetGR.getValue('u_status')
            };
        }

        // Feedback
        data.feedback = [];
        var feedbackGR = new GlideRecord('x_1790227_event_ma_feedback');
        feedbackGR.addQuery('u_event_id', eventId);
        feedbackGR.query();
        while (feedbackGR.next()) {
            data.feedback.push({ rating: feedbackGR.getValue('u_rating'), comments: feedbackGR.getValue('u_comments') });
        }

        return JSON.stringify(data);
    },

    type: 'EventDashboardUtils'
});
